import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

export default function Login() {
  const [email, setEmail]     = useState('');
  const [password, setPassword] = useState('');
  const [showPwd, setShowPwd] = useState(false);
  const [error, setError]     = useState('');
  const [loading, setLoading] = useState(false);
  const { login }  = useAuth();
  const navigate   = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      await login(email, password);
      navigate('/');
    } catch (err) {
      setError('Email ou mot de passe incorrect');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={S.bg}>
      <div style={S.box}>
        <div style={S.topBar}/>
        <div style={S.logo}>INDUSTRIOT</div>
        <h1 style={S.title}>Connexion</h1>
        <p style={S.sub}>Plateforme de supervision industrielle</p>

        {error && <div style={S.error}>{error}</div>}

        <form onSubmit={handleSubmit}>
          <div style={S.field}>
            <label style={S.label}>EMAIL</label>
            <input
              style={S.input}
              type="email"
              value={email}
              onChange={e => setEmail(e.target.value)}
              placeholder="admin@usine.local"
              required
            />
          </div>
          <div style={S.field}>
            <label style={S.label}>MOT DE PASSE</label>
            <div style={S.inputWrap}>
              <input
                style={{...S.input, paddingRight:44}}
                type={showPwd ? 'text' : 'password'}
                value={password}
                onChange={e => setPassword(e.target.value)}
                placeholder="••••••••"
                required
              />
              <button
                type="button"
                style={S.eyeBtn}
                onClick={() => setShowPwd(!showPwd)}
              >
                {showPwd ? (
                  <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.8">
                    <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94"/>
                    <path d="M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19"/>
                    <line x1="1" y1="1" x2="23" y2="23"/>
                  </svg>
                ) : (
                  <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.8">
                    <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/>
                    <circle cx="12" cy="12" r="3"/>
                  </svg>
                )}
              </button>
            </div>
          </div>
          <button style={S.btn} type="submit" disabled={loading}>
            {loading ? 'Connexion...' : 'Se connecter'}
          </button>
        </form>
      </div>
    </div>
  );
}

const S = {
  bg:        { minHeight:'100vh', background:'#1c2129', display:'flex', alignItems:'center', justifyContent:'center', fontFamily:'sans-serif' },
  box:       { width:380, background:'#161b22', border:'1px solid rgba(255,255,255,0.12)', borderRadius:12, padding:'40px 36px', position:'relative', overflow:'hidden' },
  topBar:    { position:'absolute', top:0, left:0, right:0, height:2, background:'linear-gradient(90deg, #00d4aa, #0099ff)' },
  logo:      { fontFamily:'monospace', fontSize:11, color:'#00d4aa', letterSpacing:3, marginBottom:8 },
  title:     { fontSize:22, fontWeight:600, color:'#e8eaf0', marginBottom:4 },
  sub:       { fontSize:13, color:'#7a8394', marginBottom:28 },
  field:     { marginBottom:14 },
  label:     { display:'block', fontSize:11, color:'#7a8394', letterSpacing:1, marginBottom:7, fontFamily:'monospace' },
  inputWrap: { position:'relative', display:'flex', alignItems:'center' },
  input:     { width:'100%', padding:'10px 14px', background:'#1c2129', border:'1px solid rgba(255,255,255,0.12)', borderRadius:7, color:'#e8eaf0', fontSize:13, outline:'none', boxSizing:'border-box' },
  eyeBtn:    { position:'absolute', right:12, background:'none', border:'none', cursor:'pointer', color:'#7a8394', display:'flex', alignItems:'center', padding:0 },
  btn:       { width:'100%', marginTop:20, padding:12, background:'#00d4aa', border:'none', borderRadius:7, color:'#0a0c0f', fontWeight:600, fontSize:14, cursor:'pointer' },
  error:     { background:'rgba(255,71,87,0.1)', border:'1px solid rgba(255,71,87,0.3)', color:'#ff4757', padding:'10px 14px', borderRadius:7, fontSize:13, marginBottom:16 },
};
